import{_ as l,l as n,o as e,c as i,v as t,p as s,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"SMT 求解器","description":"","frontmatter":{"title":"SMT 求解器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/smt-solver.md","filePath":"cs/smt-solver.md","lastUpdated":1789023840000}'),c={name:"cs/smt-solver.md"};function m(T,a,S,_,A,u){const o=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="smt-求解器" tabindex="-1">SMT 求解器 <a class="header-anchor" href="#smt-求解器" aria-label="Permalink to &quot;SMT 求解器&quot;">​</a></h1><div class="epigraph"><p>SAT 模理论：命题骨架仍由 CDCL 管，算术、数组、位向量各有判定器，通过理论传播与冲突把等式送回布尔层。Nelson–Oppen 组合无量词的稳定理论。</p><footer>—— 据 Nelson and Oppen, 1979；Barrett et al., SMT-LIB；Kroening and Strichman 整理</footer></div><p>上一课<a href="/cs/dpll-cdcl">CDCL</a> 只懂 0-1 子句。Hoare 的 VC 含 \\(i+1\\lt n\\)、数组读。缺口是 <strong>SMT</strong>：\\(\\mathrm{QF\\_LIA}\\)、\\(\\mathrm{QF\\_BV}\\)、数组。本课钉 DPLL(T) 形状，不把一阶完全性请回来——带量词的碎片许多不可判定，求解器靠实例化启发式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>原子可以是 \\(x+y\\le 3\\)、\\(a[i]=v\\)。布尔结构仍 CNF。理论求解器 \\(T\\)：给定文字集，判定合取是否 \\(T\\)-可满足，并推出更多文字（传播）或解释。冲突：理论不可满足的核，学布尔子句。等式共享用 E-图（Congruence closure）。Nelson–Oppen：稳定、无量词、签名不交的理论，靠等式交换组合。</p><p>位向量：本质是 SAT 爆破或位级传播，规模随位宽。</p><h3 id="不是「prolog」" tabindex="-1">不是「Prolog」 <a class="header-anchor" href="#不是「prolog」" aria-label="Permalink to &quot;不是「Prolog」&quot;">​</a></h3><p>SMT 主要无量词或有限实例化。Horn 子句、Prolog 是另一搜索。Z3 能跑的量词是 E-matching，不完备。</p><p><span class="marginnote">Nelson–Oppen 1979。DPLL(T)：Nieuwenhuis、Oliveras、Tinelli。SMT-LIB 标准。Kroening–Strichman 教材。本课不写 Simplex 全部枢轴。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>举 \\(x=y\\land f(x)\\ne f(y)\\) 的冲突（同余）。举线性不等式与布尔开关。指出：不可判定理论被切成可判定的 QF 碎片。对照<a href="/cs/predicate-logic">谓词逻辑</a> 的一般不可判定：SMT 活在可判定岛上。</p>',11)),(e(),s(h,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOOL%5B%22CDCL%20%E5%B8%83%E5%B0%94%E9%AA%A8%E6%9E%B6%22%5D%20--%3E%20T%5B%22%E7%90%86%E8%AE%BA%E6%B1%82%E8%A7%A3%E5%99%A8%22%5D%0A%20%20T%20--%3E%20PROP%5B%22%E4%BC%A0%E6%92%AD%E6%96%87%E5%AD%97%20%2F%20%E5%86%B2%E7%AA%81%E6%A0%B8%22%5D%0A%20%20PROP%20--%3E%20BOOL%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>程序验证：wp 生成一阶 VC，量化数组用选择公理图式实例化，落到 QF 片段再 SMT。失败模型给反例赋值。可靠相对理论公理；完备只在声明的可判定碎片内。</p><p>与 LWE、数论无关：整数在 SMT 里是线性算术，不是 RSA 模。</p><p>Simplex 处理 QF_LRA；位向量可 bit-blast 成 SAT。数组：读写公理 \\(\\mathrm{read}(\\mathrm{write}(a,i,v),j)\\)。字符串、浮点是后加理论，可判定性各异。量词实例化不完备：助手 hammers 调用 SMT 得到的是「这碎片上 sat/unsat」，不是一阶完备性。与模 \\(pq\\) 密码算术不是同一求解器配置。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列全部 SMT-LIB 逻辑，不写字符串理论。不把神经网络验证当主线。后课默认：含算术的 VC 走 DPLL(T)。下一课交互证明助手与依值类型，补上 SMT 不覆盖的构造性证明。</p><p>DPLL(T) 让算术、数组、位向量把文字传播回 CDCL。可判定性停在声明的 QF 碎片；量词 E-matching 不完备。VC 生成之后的自动层在此；构造性证明对象下一课助手。</p><p>上一课留下的缺口在本课收口；「SMT 求解器」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SMT = CDCL + 理论判定/传播。</li><li>无量词稳定理论可 Nelson–Oppen 组合。</li><li>量词靠启发式；一般一阶仍不可判定。</li><li>出处：Nelson and Oppen, 1979；SMT-LIB；Kroening and Strichman。</li></ul>',10))])}const P=l(c,[["render",m]]);export{f as __pageData,P as default};
